export const fail = (): never => {
  throw { code: 1 };
};

export const fail = (code: number): never => {
  throw `failed ${code}`;
};

export const fail = (): never => {
  throw undefined;
};

export const fail = (ready: string): never => {
  throw ready === "yes" ? new Error("x") : "x";
};

